// The reference values in this module are generated with the reference implementation of SGP4 of Vallado, D. A.,
// Crawford, P., Hujsak, R., & Kelso, T. S. (2006), "Revisiting Spacetrack Report #3", AIAA 2006-6753, e.g., its C++
// implementation, as bound by the sgp4 package (version 2.24).
//
// The element sets are those of the verification set of that paper, e.g., SGP4-VER.TLE, of both the near-Earth and
// the deep-space theory, each propagated over the times of its verification run, e.g., the start, stop and step
// carried beyond the 69th column of its second line, with the gravity model of WGS 72 in the improved mode of
// operation, six of the deep-space element sets in the mode of operation of the Air Force Space Command also, and
// three of them with the gravity models of WGS 72 (old) and WGS 84 also.
//
// N.B. The element sets of the satellites 33333, 33334 and 33335 are deliberately corrupted by the verification set,
// e.g., their checksums are not those of their lines, and so they are given without their checksums, which are not
// verified then, as the reference implementation does not verify them.
//
// The states are those of the reference implementation, e.g., in the True Equator, Mean Equinox (TEME) frame of the
// epoch, in kilometres and kilometres per second. Where the reference implementation fails, the propagation of the
// element set stops at the time of the failure, and its error code is recorded.

/*****************************************************************************************************************/

export interface SGP4StateReference {
  // The time since the epoch of the element set (in minutes):
  minutes: number
  // The position of the object, in the TEME frame (in kilometres):
  position: [number, number, number]
  // The velocity of the object, in the TEME frame (in kilometres per second):
  velocity: [number, number, number]
}

/*****************************************************************************************************************/

export interface SGP4Reference {
  // The satellite catalogue number of the element set:
  satellite: number
  // The first line of the element set:
  line1: string
  // The second line of the element set:
  line2: string
  // The gravity model the element set is propagated with:
  gravity: 'WGS72OLD' | 'WGS72' | 'WGS84'
  // The mode of operation of the theory the element set is propagated with:
  mode: 'improved' | 'afspc'
  // The states of the object over the times of its verification run:
  states: SGP4StateReference[]
  // The failure of the reference implementation, e.g., the time and the error code of it, where it fails:
  error?: { minutes: number; code: number }
}

/*****************************************************************************************************************/

